    38	static void print_req(gnutls_buffer_st * str, gnutls_ocsp_req_t req)
    39	{
    40	        int ret;
    41	        unsigned indx;
    42	
    43	        /* Version. */
    44	        {
    45	                int version = gnutls_ocsp_req_get_version(req);
    46	                if (version < 0)
    47	                        addf(str, "error: get_version: %s\n",
    48	                             gnutls_strerror(version));
    49	                else
    50	                        addf(str, _("\tVersion: %d\n"), version);
    51	        }
    52	
    53	        /* XXX requestorName */
    54	
    55	        /* requestList */
    56	        addf(str, "\tRequest List:\n");
    57	        for (indx = 0;; indx++) {
    58	                gnutls_digest_algorithm_t digest;
    59	                gnutls_datum_t in, ik, sn;
    60	
    61	                ret =
    62	                    gnutls_ocsp_req_get_cert_id(req, indx, &digest, &in,
    63	                                                &ik, &sn);
    64	                if (ret == GNUTLS_E_REQUESTED_DATA_NOT_AVAILABLE)
    65	                        break;
    66	                addf(str, "\t\tCertificate ID:\n");
    67	                if (ret != GNUTLS_E_SUCCESS) {
    68	                        addf(str, "error: get_cert_id: %s\n",
    69	                             gnutls_strerror(ret));
    70	                        continue;
    71	                }
    72	                addf(str, "\t\t\tHash Algorithm: %s\n",
    73	                     _gnutls_digest_get_name(hash_to_entry(digest)));
    74	
    75	                adds(str, "\t\t\tIssuer Name Hash: ");
    76	                _gnutls_buffer_hexprint(str, in.data, in.size);
    77	                adds(str, "\n");
    78	
    79	                adds(str, "\t\t\tIssuer Key Hash: ");
    80	                _gnutls_buffer_hexprint(str, ik.data, ik.size);
    81	                adds(str, "\n");
    82	
    83	                adds(str, "\t\t\tSerial Number: ");
    84	                _gnutls_buffer_hexprint(str, sn.data, sn.size);
    85	                adds(str, "\n");
    86	
    87	                gnutls_free(in.data);
    88	                gnutls_free(ik.data);
    89	                gnutls_free(sn.data);
    90	
    91	                /* XXX singleRequestExtensions */
    92	        }
    93	
    94	        for (indx = 0;; indx++) {
    95	                gnutls_datum_t oid;
    96	                unsigned int critical;
    97	                gnutls_datum_t data;
    98	
    99	                ret =
   100	                    gnutls_ocsp_req_get_extension(req, indx, &oid,
   101	                                                  &critical, &data);
   102	                if (ret == GNUTLS_E_REQUESTED_DATA_NOT_AVAILABLE)
   103	                        break;
   104	                else if (ret != GNUTLS_E_SUCCESS) {
   105	                        addf(str, "error: get_extension: %s\n",
   106	                             gnutls_strerror(ret));
   107	                        continue;
   108	                }
   109	                if (indx == 0)
   110	                        adds(str, "\tExtensions:\n");
   111	
   112	                if (oid.size == sizeof(GNUTLS_OCSP_NONCE) &&
   113	                    memcmp(oid.data, GNUTLS_OCSP_NONCE, oid.size) == 0) {
   114	                        gnutls_datum_t nonce;
   115	                        unsigned int ncrit;
   116	
   117	                        ret =
   118	                            gnutls_ocsp_req_get_nonce(req, &ncrit,
   119	                                                      &nonce);
   120	                        if (ret != GNUTLS_E_SUCCESS) {
   121	                                addf(str, "error: get_nonce: %s\n",
   122	                                     gnutls_strerror(ret));
   123	                        } else {
   124	                                addf(str, "\t\tNonce%s: ",
   125	                                     ncrit ? " (critical)" : "");
   126	                                _gnutls_buffer_hexprint(str, nonce.data,
   127	                                                        nonce.size);
   128	                                adds(str, "\n");
   129	                                gnutls_free(nonce.data);
   130	                        }
   131	                } else {
   132	                        addf(str, "\t\tUnknown extension %s (%s):\n",
   133	                             oid.data,
   134	                             critical ? "critical" : "not critical");
   135	
   136	                        adds(str, _("\t\t\tASCII: "));
   137	                        _gnutls_buffer_asciiprint(str, (char *) data.data,
   138	                                                  data.size);
   139	                        addf(str, "\n");
   140	
   141	                        adds(str, _("\t\t\tHexdump: "));
   142	                        _gnutls_buffer_hexprint(str, (char *) data.data,
   143	                                                data.size);
   144	                        adds(str, "\n");
   145	                }
   146	
   147	                gnutls_free(oid.data);
   148	                gnutls_free(data.data);
   149	        }
