   211	        }
   212	
   213	        adds(str, "\tResponse Status: ");
   214	        switch (ret) {
   215	        case GNUTLS_OCSP_RESP_SUCCESSFUL:
   216	                adds(str, "Successful\n");
   217	                break;
   218	
   219	        case GNUTLS_OCSP_RESP_MALFORMEDREQUEST:
   220	                adds(str, "malformedRequest\n");
   221	                return;
   222	
   223	        case GNUTLS_OCSP_RESP_INTERNALERROR:
   224	                adds(str, "internalError\n");
   225	                return;
   226	
   227	        case GNUTLS_OCSP_RESP_TRYLATER:
   228	                adds(str, "tryLater\n");
   229	                return;
   230	
   231	        case GNUTLS_OCSP_RESP_SIGREQUIRED:
   232	                adds(str, "sigRequired\n");
   233	                return;
   234	
   235	        case GNUTLS_OCSP_RESP_UNAUTHORIZED:
   236	                adds(str, "unauthorized\n");
   237	                return;
   238	
   239	        default:
   240	                adds(str, "unknown\n");
   241	                return;
   242	        }
   243	
   244	        {
   245	                gnutls_datum_t oid;
   246	
   247	                ret = gnutls_ocsp_resp_get_response(resp, &oid, NULL);
   248	                if (ret < 0) {
   249	                        addf(str, "error: get_response: %s\n",
   250	                             gnutls_strerror(ret));
   251	                        return;
   252	                }
   253	
   254	                adds(str, "\tResponse Type: ");
   255	#define OCSP_BASIC "1.3.6.1.5.5.7.48.1.1"
   256	
   257	                if (oid.size == sizeof(OCSP_BASIC)
   258	                    && memcmp(oid.data, OCSP_BASIC, oid.size) == 0) {
   259	                        adds(str, "Basic OCSP Response\n");
   260	                        gnutls_free(oid.data);
   261	                } else {
   262	                        addf(str, "Unknown response type (%.*s)\n",
   263	                             oid.size, oid.data);
   264	                        gnutls_free(oid.data);
   265	                        return;
   266	                }
   267	        }
   268	
   269	        /* Version. */
   270	        {
   271	                int version = gnutls_ocsp_resp_get_version(resp);
   272	                if (version < 0)
   273	                        addf(str, "error: get_version: %s\n",
   274	                             gnutls_strerror(version));
   275	                else
   276	                        addf(str, _("\tVersion: %d\n"), version);
   277	        }
   278	
   279	        /* responderID */
   280	        {
   281	                gnutls_datum_t dn = {NULL, 0};
   282	
   283	                ret = gnutls_ocsp_resp_get_responder2(resp, &dn, 0);
   284	                if (ret < 0) {
   285	                        if (ret == GNUTLS_E_REQUESTED_DATA_NOT_AVAILABLE) {
   286	                                ret = gnutls_ocsp_resp_get_responder_raw_id(resp, GNUTLS_OCSP_RESP_ID_KEY, &dn);
   287	
   288	                                if (ret >= 0) {
   289	                                        addf(str, _("\tResponder Key ID: "));
   290	                                        _gnutls_buffer_hexprint(str, dn.data, dn.size);
   291	                                        adds(str, "\n");
   292	                                }
   293	                                gnutls_free(dn.data);
   294	                        } else {
   295	                                addf(str, "error: get_responder2: %s\n",
   296	                                     gnutls_strerror(ret));
   297	                        }
   298	                } else {
   299	                        addf(str, _("\tResponder ID: %s\n"), dn.data);
   300	                        gnutls_free(dn.data);
   301	                }
   302	        }
   303	
   304	        {
   305	                char s[42];
   306	                size_t max = sizeof(s);
   307	                struct tm t;
   308	                time_t tim = gnutls_ocsp_resp_get_produced(resp);
   309	
   310	                if (tim == (time_t) - 1)
   311	                        addf(str, "error: ocsp_resp_get_produced\n");
   312	                else if (gmtime_r(&tim, &t) == NULL)
   313	                        addf(str, "error: gmtime_r (%ld)\n",
   314	                             (unsigned long) tim);
   315	                else if (strftime(s, max, "%a %b %d %H:%M:%S UTC %Y", &t)
   316	                         == 0)
   317	                        addf(str, "error: strftime (%ld)\n",
   318	                             (unsigned long) tim);
   319	                else
   320	                        addf(str, _("\tProduced At: %s\n"), s);
