   330	                time_t revocation_time;
   331	                unsigned int revocation_reason;
   332	
   333	                ret = gnutls_ocsp_resp_get_single(resp,
   334	                                                  indx,
   335	                                                  &digest, &in, &ik, &sn,
   336	                                                  &cert_status,
   337	                                                  &this_update,
   338	                                                  &next_update,
   339	                                                  &revocation_time,
   340	                                                  &revocation_reason);
   341	                if (ret == GNUTLS_E_REQUESTED_DATA_NOT_AVAILABLE)
   342	                        break;
   343	                addf(str, "\t\tCertificate ID:\n");
   344	                if (ret != GNUTLS_E_SUCCESS) {
   345	                        addf(str, "error: get_singleresponse: %s\n",
   346	                             gnutls_strerror(ret));
   347	                        continue;
   348	                }
   349	                addf(str, "\t\t\tHash Algorithm: %s\n",
   350	                     _gnutls_digest_get_name(hash_to_entry(digest)));
   351	
   352	                adds(str, "\t\t\tIssuer Name Hash: ");
   353	                _gnutls_buffer_hexprint(str, in.data, in.size);
   354	                adds(str, "\n");
   355	
   356	                adds(str, "\t\t\tIssuer Key Hash: ");
   357	                _gnutls_buffer_hexprint(str, ik.data, ik.size);
   358	                adds(str, "\n");
   359	
   360	                adds(str, "\t\t\tSerial Number: ");
   361	                _gnutls_buffer_hexprint(str, sn.data, sn.size);
   362	                adds(str, "\n");
   363	
   364	                gnutls_free(in.data);
   365	                gnutls_free(ik.data);
   366	                gnutls_free(sn.data);
   367	
   368	                {
   369	                        const char *p = NULL;
   370	
   371	                        switch (cert_status) {
   372	                        case GNUTLS_OCSP_CERT_GOOD:
   373	                                p = "good";
   374	                                break;
   375	
   376	                        case GNUTLS_OCSP_CERT_REVOKED:
   377	                                p = "revoked";
   378	                                break;
   379	
   380	                        case GNUTLS_OCSP_CERT_UNKNOWN:
   381	                                p = "unknown";
   382	                                break;
   383	
   384	                        default:
   385	                                addf(str,
   386	                                     "\t\tCertificate Status: unexpected value %d\n",
   387	                                     cert_status);
   388	                                break;
   389	                        }
   390	
   391	                        if (p)
   392	                                addf(str, "\t\tCertificate Status: %s\n",
   393	                                     p);
   394	                }
