   396	                /* XXX revocation reason */
   397	
   398	                if (cert_status == GNUTLS_OCSP_CERT_REVOKED) {
   399	                        char s[42];
   400	                        size_t max = sizeof(s);
   401	                        struct tm t;
   402	
   403	                        if (revocation_time == (time_t) - 1)
   404	                                addf(str, "error: revocation_time\n");
   405	                        else if (gmtime_r(&revocation_time, &t) == NULL)
   406	                                addf(str, "error: gmtime_r (%ld)\n",
   407	                                     (unsigned long) revocation_time);
   408	                        else if (strftime
   409	                                 (s, max, "%a %b %d %H:%M:%S UTC %Y",
   410	                                  &t) == 0)
   411	                                addf(str, "error: strftime (%ld)\n",
   412	                                     (unsigned long) revocation_time);
   413	                        else
   414	                                addf(str, _("\t\tRevocation time: %s\n"),
   415	                                     s);
   416	                }
   417	
   418	                {
   419	                        char s[42];
   420	                        size_t max = sizeof(s);
   421	                        struct tm t;
   422	
