   435	                }
   436	
   437	                {
   438	                        char s[42];
   439	                        size_t max = sizeof(s);
   440	                        struct tm t;
   441	
   442	                        if (next_update != (time_t) - 1) {
   443	                                if (gmtime_r(&next_update, &t) == NULL)
   444	                                        addf(str, "error: gmtime_r (%ld)\n",
