   512	                gnutls_free(data.data);
   513	
   514	        }
   515	
   516	        ret = gnutls_ocsp_resp_get_signature_algorithm(resp);
   517	        if (ret < 0)
   518	                addf(str, "error: get_signature_algorithm: %s\n",
   519	                     gnutls_strerror(ret));
   520	        else {
   521	                const char *name =
   522	                    gnutls_sign_algorithm_get_name(ret);
   523	                if (name == NULL)
